package com.tickethub.paymentservice.config;
import com.tickethub.paymentservice.security.JwtAuthenticationFilter; import org.springframework.context.annotation.*; import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.web.*; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;
@Configuration @EnableMethodSecurity public class SecurityConfig {@Bean SecurityFilterChain security(HttpSecurity http,JwtAuthenticationFilter filter)throws Exception{return http.csrf(c->c.disable()).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/actuator/**","/swagger-ui/**","/swagger-ui.html","/v3/api-docs/**","/api/payments/webhook","/checkout-test.html","/favicon.ico").permitAll().requestMatchers("/api/payments/**").authenticated().anyRequest().authenticated()).exceptionHandling(e->e.authenticationEntryPoint((req,res,ex)->res.sendError(401,"Unauthorized")).accessDeniedHandler((req,res,ex)->res.sendError(403,"Forbidden"))).addFilterBefore(filter,UsernamePasswordAuthenticationFilter.class).build();}}
